function validate([isInfected]) {
  if (!Array.isArray(isInfected) || isInfected.length < 1 || isInfected.length > 50) return 'isInfected needs 1 to 50 rows.';
  const m = isInfected.length, n = Array.isArray(isInfected[0]) ? isInfected[0].length : 0;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 cells.';
  if (isInfected.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (isInfected.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  // Replay the outbreak to make sure no day has a tie for the most threatened cells.
  const grid = isInfected.map(row => row.slice());
  for (;;) {
    const id = grid.map(row => row.map(() => -1));
    const groups = [];
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (grid[i][j] !== 1 || id[i][j] >= 0) continue;
      const g = { cells: [], threat: new Set() };
      id[i][j] = groups.length;
      const queue = [[i, j]];
      while (queue.length) {
        const [a, b] = queue.pop();
        g.cells.push([a, b]);
        for (const [x, y] of [[a + 1, b], [a - 1, b], [a, b + 1], [a, b - 1]]) {
          if (x < 0 || y < 0 || x >= m || y >= n) continue;
          if (grid[x][y] === 0) g.threat.add(x * n + y);
          else if (grid[x][y] === 1 && id[x][y] < 0) { id[x][y] = groups.length; queue.push([x, y]); }
        }
      }
      groups.push(g);
    }
    const sizes = groups.map(g => g.threat.size).sort((a, b) => b - a);
    if (!sizes.length || sizes[0] === 0) return null;
    if (sizes.length > 1 && sizes[0] === sizes[1]) return 'On some day two regions tie for the most threatened cells; the problem rules that out.';
    const top = groups.find(g => g.threat.size === sizes[0]);
    for (const [a, b] of top.cells) grid[a][b] = 2;
    for (const g of groups) if (g !== top) for (const c of g.threat) grid[Math.floor(c / n)][c % n] = 1;
  }
}

