function containVirus(isInfected) {
  const grid = isInfected.map(row => row.slice());
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let walls = 0;
  while (true) {
    const seen = grid.map(row => row.map(() => false));
    const regions = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (grid[r][c] !== 1 || seen[r][c]) continue;
        const region = { cells: [], threatened: new Set(), perimeter: 0 };
        const stack = [[r, c]];
        seen[r][c] = true;
        while (stack.length > 0) {
          const [row, col] = stack.pop();
          region.cells.push([row, col]);
          for (const [dr, dc] of directions) {
            const nextRow = row + dr;
            const nextCol = col + dc;
            if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
            if (grid[nextRow][nextCol] === 0) {
              region.threatened.add(nextRow * cols + nextCol);
              region.perimeter++;
            } else if (grid[nextRow][nextCol] === 1 && !seen[nextRow][nextCol]) {
              seen[nextRow][nextCol] = true;
              stack.push([nextRow, nextCol]);
            }
          }
        }
        regions.push(region);
      }
    }
    let worst = null;
    for (const region of regions) {
      if (worst === null || region.threatened.size > worst.threatened.size) {
        worst = region;
      }
    }
    if (worst === null || worst.threatened.size === 0) break;
    walls += worst.perimeter;
    for (const [row, col] of worst.cells) {
      grid[row][col] = 2;
    }
    for (const region of regions) {
      if (region === worst) continue;
      for (const cell of region.threatened) {
        grid[Math.floor(cell / cols)][cell % cols] = 1;
      }
    }
  }
  return walls;
}

