function containVirus(isInfected) {
  // Works from the healthy cells' side: label regions by spreading the smallest cell id, then let every healthy cell
  // report which regions touch it and through how many sides.
  let grid = isInfected.map(row => row.slice());
  const m = grid.length, n = grid[0].length;
  const near = (i, j) => [[i - 1, j], [i + 1, j], [i, j - 1], [i, j + 1]].filter(([a, b]) => a >= 0 && a < m && b >= 0 && b < n);
  let total = 0;
  for (;;) {
    const label = grid.map((row, i) => row.map((v, j) => (v === 1 ? i * n + j : -1)));
    let changed = true;
    while (changed) {
      changed = false;
      for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        if (label[i][j] < 0) continue;
        for (const [a, b] of near(i, j)) if (label[a][b] >= 0 && label[a][b] < label[i][j]) { label[i][j] = label[a][b]; changed = true; }
      }
    }
    const threat = new Map(), sides = new Map();
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (grid[i][j] !== 0) continue;
      const touching = near(i, j).map(([a, b]) => label[a][b]).filter(l => l >= 0);
      for (const l of touching) sides.set(l, (sides.get(l) || 0) + 1);
      for (const l of new Set(touching)) threat.set(l, (threat.get(l) || 0) + 1);
    }
    if (threat.size === 0) return total;
    let pick = -1;
    for (const [l, count] of threat) if (pick < 0 || count > threat.get(pick)) pick = l;
    total += sides.get(pick);
    grid = grid.map((row, i) => row.map((v, j) => {
      if (label[i][j] === pick) return 2;
      if (v === 0 && near(i, j).some(([a, b]) => label[a][b] >= 0 && label[a][b] !== pick)) return 1;
      return v;
    }));
  }
}

